import {trackNames} from '../timeline/graph.js';
import {find,isLocked} from '../document/model.js';
import {allTracks} from '../animation/evaluate.js';
import {escape} from '../renderer/svg.js';
export const keyEaseProfiles=[{id:'linear',name:'Linear',detail:'Constant speed'},{id:'easeIn',name:'Ease in',detail:'Speed up'},{id:'easeOut',name:'Ease out',detail:'Slow down'},{id:'easeInOut',name:'Ease in & out',detail:'Smooth start and end'},{id:'slowStart',name:'Slow start',detail:'Longer gentle start',bezier:[.7,0,1,1]},{id:'slowEnd',name:'Slow end',detail:'Longer gentle finish',bezier:[0,0,.3,1]},{id:'bounceIn',name:'Bounce in',detail:'Rebounds before departing'},{id:'bounceOut',name:'Bounce out',detail:'Rebounds as it lands'},{id:'hold',name:'Hold',detail:'Jump at the next key'}];
export function keyEaseTarget(a,id,prop,keyid){const n=find(a.doc,id);if(!n||isLocked(a.doc,id))return null;for(const tracks of allTracks(n)){const track=tracks[prop],index=track?.findIndex(k=>k.id===keyid);if(index>=0)return {n,track,k:track[index],next:track[index+1]};}return null;}
export function applyKeyEase(a,id,prop,keyid,profile){const choice=keyEaseProfiles.find(p=>p.id===profile),target=keyEaseTarget(a,id,prop,keyid);if(!choice||!target?.next)return false;a.mutate('Keyframe easing',()=>{const current=keyEaseTarget(a,id,prop,keyid);if(!current?.next)return;current.k.easing=choice.bezier?'linear':choice.id;if(choice.bezier)current.k.bezier=[...choice.bezier];else delete current.k.bezier;});return true;}
export function showKeyEasing(a,{n,prop,k}){const doc=a.doc,id=n.id,keyid=k.id,target=keyEaseTarget(a,id,prop,keyid);if(!target)return;a.activeKeyEaseDialog?.close();const d=a.dialog('Keyframe easing',`<p><strong>${escape(n.name)} · ${escape(trackNames[prop]||prop)}</strong></p><p class="subtle">Tween from this key to the next key. Earlier motion and other tracks stay unchanged.</p>${target.next?'':'<p>This is the last key. Add a later key to tween toward it.</p>'}<div class="key-ease-profiles">${keyEaseProfiles.map(p=>`<button type="button" data-key-ease="${p.id}" ${target.next?'':'disabled'} aria-pressed="false"><strong>${p.name}</strong><small>${p.detail}</small></button>`).join('')}</div><div class="dialog-actions"><button type="button" data-close>Done</button></div>`,undefined,{modal:false});a.activeKeyEaseDialog=d;d.classList.add('key-easing-dialog');const refresh=()=>{const current=keyEaseTarget(a,id,prop,keyid);for(const b of d.querySelectorAll('[data-key-ease]')){const p=keyEaseProfiles.find(p=>p.id===b.dataset.keyEase),selected=current&&(p.bezier?JSON.stringify(p.bezier)===JSON.stringify(current.k.bezier):!current.k.bezier&&current.k.easing===p.id);b.setAttribute('aria-pressed',!!selected);}};for(const b of d.querySelectorAll('[data-key-ease]'))b.onclick=()=>{if(a.doc!==doc||!a.keyIds.has(keyid))return d.close();applyKeyEase(a,id,prop,keyid,b.dataset.keyEase);refresh();};const outside=e=>{if(!d.contains(e.target))d.close();};document.addEventListener('pointerdown',outside,true);d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();d.close();}});d.addEventListener('close',()=>{document.removeEventListener('pointerdown',outside,true);if(a.activeKeyEaseDialog===d)a.activeKeyEaseDialog=null;},{once:true});refresh();return d;}
